/**
 * @name XPath injection vulnerability in lxml
 * @description Untrusted input flowing into XPath evaluation can lead to data disclosure or DoS
 * @kind path-problem
 * @problem.severity error
 * @id py/xpath-injection-lxml
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XPath evaluation methods in lxml
    exists(API::CallNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember("_Element").getMember("xpath").getACall()
      and sink = call.getArg(0)
    )
  }
}

module XPathFlow = TaintTracking::Global<XPathConfig>;
import XPathFlow::PathGraph

from XPathFlow::PathNode source, XPathFlow::PathNode sink
where XPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XPath injection from $@.", source.getNode(), "user input"

/**
 * @name XSLT injection vulnerability in lxml
 * @description XSLT processing with untrusted stylesheets can lead to code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/xslt-injection
 * @tags security
 *        external/cwe/cwe-91
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XSLTConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XSLT processing in lxml - check for etree.XSLT constructor
    exists(API::CallNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember("XSLT").getACall()
      and sink = call.getArg(0)
    )
    or
    // Check for XSLT.apply method
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember("XSLT").getMember("apply").getACall()
      and sink = call.getArg(0)
    )
    or
    // Check for XSLT.__call__ method
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember("XSLT").getMember("__call__").getACall()
      and sink = call.getArg(0)
    )
  }
}

module XSLTFlow = TaintTracking::Global<XSLTConfig>;
import XSLTFlow::PathGraph

from XSLTFlow::PathNode source, XSLTFlow::PathNode sink
where XSLTFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XSLT injection from $@.", source.getNode(), "user input"
